    this.lonScale = LON_SCALE;
    this.latDecode = LAT_DECODE;
    this.lonDecode = LON_DECODE;
    this.coordinateBounds = new double[] {MIN_LAT_INCL, MAX_LAT_INCL, MIN_LON_INCL, MAX_LON_INCL};
    this.minLatRadians = Math.toRadians(MIN_LAT_INCL);
    this.maxLatRadians = Math.toRadians(MAX_LAT_INCL);
    this.minLonRadians = Math.toRadians(MIN_LON_INCL);
    this.maxLonRadians = Math.toRadians(MAX_LON_INCL);
    this.earthMeanRadiusMeters = GeoUtils.EARTH_MEAN_RADIUS_METERS;
    this.axisLatError = Math.toDegrees(0.1D / GeoUtils.EARTH_MEAN_RADIUS_METERS);
