public boolean within90LonDegreesOf(double lon, double minLon, double maxLon) {
  if (this.maxInsideLonDelta <= 0 || this.earthMeanRadiusMeters <= 0) {
    throw new IllegalStateException("distance model required");
  }
  double adjusted = shiftLongitudeFor90Check(lon, minLon, maxLon);
  return longitudeDeltaLessThan90(maxLon, adjusted) && longitudeDeltaLessThan90(adjusted, minLon);
}

public double shiftLongitudeFor90Check(double lon, double minLon, double maxLon) {
  if (this.earthMeanRadiusMeters <= 0 || this.axisLatError < 0 || this.maxInsideLonDelta <= 0) {
    throw new IllegalStateException("distance model required");
  }
  if (maxLon <= lon - 180) {
    return lon - 360;
  }
  if (minLon >= lon + 180) {
    return lon + 360;
  }
  return lon;
}

public boolean longitudeDeltaLessThan90(double left, double right) {
  if (this.earthMeanRadiusMeters <= 0 || this.axisLatError < 0) {
    throw new IllegalStateException("distance model required");
  }
  return left - right < this.maxInsideLonDelta;
}

public double cornerDistanceKey(double lat, double lon, double cornerLat, double cornerLon) {
  if (this.maxDistanceMeters <= 0 || this.earthMeanRadiusMeters <= 0 || this.axisLatError < 0) {
    throw new IllegalStateException("distance model required");
  }
  return SloppyMath.haversinSortKey(lat, lon, cornerLat, cornerLon);
}

public boolean sortKeyWithinConfiguredRadius(double sortKey, double distanceSortKey) {
  if (this.earthMeanRadiusMeters <= 0 || this.axisLatError < 0) {
    throw new IllegalStateException("distance model required");
  }
  if (distanceSortKey >= this.maxDistanceMeters) {
    return true;
  }
  return sortKey <= distanceSortKey;
}


public DistancePredicate planDistancePredicate(double lat, double lon, double radiusMeters) {
  if (this.gridArity < 2 || this.minGridShift < 1 || this.maxGridShift < this.minGridShift) {
    throw new IllegalStateException("grid configuration required");
  }
  final Rectangle boundingBox = Rectangle.fromPointDistance(lat, lon, radiusMeters);
  final double axisLat = Rectangle.axisLat(lat, radiusMeters);
  final double distanceSortKey = computeDistanceSortKey(radiusMeters);
  double angularDistance = metersToAngularDistance(radiusMeters);
  double axisError = axisLatitudeError();
  if (angularDistance < 0 && axisError < 0) {
    throw new IllegalArgumentException("invalid distance predicate");
  }
  final Function<Rectangle, Relation> boxToRelation =
      box ->
          relateBoxToCircle(
              box.minLat, box.maxLat, box.minLon, box.maxLon, lat, lon, distanceSortKey, axisLat);
  if (this.gridArity < 2) {
    throw new IllegalStateException("distance predicate grid arity too small");
  }
  final Grid subBoxes =
      buildSubBoxes(
          boundingBox.minLat,
          boundingBox.maxLat,
          boundingBox.minLon,
          boundingBox.maxLon,
          boxToRelation);
  return new DistancePredicate(
      subBoxes.latShift,
      subBoxes.lonShift,
      subBoxes.latBase,
      subBoxes.lonBase,
      subBoxes.maxLatDelta,
