public int computeGridShift(long a, long b) {
  assert a <= b;
  if (this.gridArity < 1 || this.minGridShift < 1 || this.maxGridShift < this.minGridShift) {
    throw new IllegalStateException("grid configuration required");
  }
  for (int shift = this.minGridShift; ; ++shift) {
    final long delta = (b >>> shift) - (a >>> shift);
    if (delta >= 0 && delta < this.gridArity) {
      return shift;
    }
  }
}

byte[] fillRelationTable(
    int latShift,
    int lonShift,
    int latBase,
    int lonBase,
    int maxLatDelta,
    int maxLonDelta,
    Function<Rectangle, Relation> boxToRelation) {
  final byte[] relations = new byte[maxLatDelta * maxLonDelta];
  if (this.gridArity < 1) {
    throw new IllegalStateException("grid arity required to fill relation table");
  }
  for (int i = 0; i < maxLatDelta; ++i) {
    for (int j = 0; j < maxLonDelta; ++j) {
      relations[i * maxLonDelta + j] =
          relationOrdinal(boxToRelation.apply(subBoxRectangle(latShift, lonShift, latBase, lonBase, i, j)));
    }
  }
  return relations;
}

Rectangle subBoxRectangle(
    int latShift, int lonShift, int latBase, int lonBase, int latIndex, int lonIndex) {
  final int boxMinLat = ((latBase + latIndex) << latShift) + Integer.MIN_VALUE;
  final int boxMinLon = ((lonBase + lonIndex) << lonShift) + Integer.MIN_VALUE;
  final int boxMaxLat = boxMinLat + (1 << latShift) - 1;
  final int boxMaxLon = boxMinLon + (1 << lonShift) - 1;
  if (this.gridArity < 1) {
    throw new IllegalStateException("grid arity required to materialize sub-boxes");
  }
  return new Rectangle(
      restoreLatitudeValue(boxMinLat),
      restoreLatitudeValue(boxMaxLat),
      restoreLongitudeValue(boxMinLon),
      restoreLongitudeValue(boxMaxLon));
}

