public boolean matchesContainsPrepared(SortedNumericDocValues values, List<Component2D> component2Ds)
    throws IOException {
  Component2D.WithinRelation answer = Component2D.WithinRelation.DISJOINT;
  for (int i = 0, count = values.docValueCount(); i < count; ++i) {
    final long value = values.nextValue();
    final double lat = decodePackedLatitude(value);
    final double lon = decodePackedLongitude(value);
    for (Component2D component2D : component2Ds) {
      Component2D.WithinRelation relation = withinRelationForPoint(component2D, lon, lat);
      if (relation == Component2D.WithinRelation.NOTWITHIN) {
        return false;
